[상속과 오버라이딩] 다음 코드에 대한 설명으로 올바른 것은?

class Animal:
    def __init__(self, name):
        self.name = name

    def speak(self):
        print("동물이 소리를 냅니다.")

class Dog(Animal):
    def __init__(self, name, breed):
        super().__init__(name)
        self.breed = breed

    def speak(self):
        print(f"{self.name}가 멍멍 짖습니다.")

dog = Dog("Bori", "Poodle")
dog.speak()

