[Wizard 상속] 다음 코드의 출력으로 올바른 것은?

class Character:
    def __init__(self, name, health):
        self.name = name
        self.health = health

    def take_damage(self, amount):
        self.health = max(0, self.health - amount)

class Wizard(Character):
    def __init__(self, name, health, mana):
        super().__init__(name, health)
        self.mana = mana

    def use_magic(self):
        if self.mana >= 10:
            self.mana -= 10

w = Wizard("Merlin", 80, 20)
w.take_damage(15)
w.use_magic()
w.use_magic()
w.use_magic()
print(w.health, w.mana)

