[__call__] 다음 코드의 출력으로 올바른 것은?

class AffineFunction:
    def __init__(self, a, b):
        self.a = a
        self.b = b

    def __call__(self, x):
        return self.a * x + self.b

f = AffineFunction(a=2, b=1)
print(f(3), f(10))

