[Dataset 필수 메서드] 다음 Dataset 클래스의 빈칸 (A), (B)에 들어갈 메서드 이름을 올바르게 짝지은 것은? (len(ds)는 샘플 수를, ds[3]은 3번 샘플을 돌려준다)

from torch.utils.data import Dataset

class MyDataset(Dataset):
    def __init__(self, x, y):
        super().__init__()
        self.x = x
        self.y = y

    def ________(self):          # (A)
        return len(self.x)

    def ________(self, index):   # (B)
        return self.x[index], self.y[index]

